	t.Setenv("INTROPY_GITOPS_REPO", "")
	gittest.WriteFile(t, filepath.Join(cfgHome, "intropy", "config.yaml"), "gitopsRepo: "+origin+"\n")

	calls := &libraryCalls{}
	srv := newInitLibraryServer(t, entries, calls)
	t.Cleanup(srv.Close)

	return initFixture{
		gitopsOrigin: origin,
		cacheRoot:    t.TempDir(),
		topologyFile: topoFile,
